  if ((o.preco || 0) >= (cfg.caroShopee || 1000) && !(o.tipoLoja || []).some(t => SHOPEE_LOJA_BOA.includes(Number(t)))) return false;
  return true;
}

function escolherShopee(lista, mem, cfg, proibidos, querEletronico = false) {
