const CUPOM_RESTRITO = /selecionad|lista|primeira compra|primeiro pedido|novos? (usu[aá]ri|client)|clientes? novos?|categoria|loja oficial|lojas? participantes|vendedor|moda|beleza|frete|moedas|cashback|meli\s*\+|prime|cart[aã]o|nubank|mercado pago|assinantes|exclusiv/i;
const BANCO_HORAS = 24;

const BANCO_HORAS_LOJA = { amazon: 3 };
const validadeBanco = (loja) => (BANCO_HORAS_LOJA[loja] || BANCO_HORAS) * 36e5;

function lojaDoCupom(p) {
  const hosts = (p.links || []).map(u => { try { return novaURL(u).hostname.toLowerCase(); } catch { return ''; } });
  if (hosts.some(h => /(^|\.)shopee\.com\.br$|(^|\.)shope\.ee$/.test(h))) return 'shopee';
  if (hosts.some(h => /(^|\.)amazon\.com\.br$|(^|\.)amzn\.to$|(^|\.)a\.co$|(^|\.)link\.amazon$/.test(h))) return 'amazon';
  const t = String(p.texto || '');
  if (/cupo\w* shopee/i.test(t)) return 'shopee';
  if (/cupo\w* amazon/i.test(t)) return 'amazon';
  return null;
}

function condicaoCupom(texto) {
  const t0 = String(texto || '').replace(/\s+/g, ' ');
  const limite = numero((t0.match(/(?:limite|m[aá]ximo)\s*(?:de)?\s*R\$\s*([\d.]+(?:,\d{1,2})?)/i) || [])[1] || '');

  const t = t0.replace(/(?:limite|m[aá]ximo)\s*(?:de)?\s*R\$\s*[\d.]+(?:,\d{1,2})?(?:\s*OFF)?/gi, '');
  const rs = t.match(/R\$\s*([\d.]+(?:,\d{1,2})?)\s*(?:OFF|de desconto)/i);
  const pc = t.match(/(\d{1,2})\s*%\s*(?:OFF|de desconto)/i);
  if (!rs && !pc) return null;
  const minimo = numero((t.match(/(?:acima de|a partir de|m[ií]nim[oa] de|compras? de)\s*R\$\s*([\d.]+(?:,\d{1,2})?)/i) || [])[1] || '');
  return rs ? { tipo: 'R$', valor: numero(rs[1]), minimo, limite: null } : { tipo: '%', valor: Number(pc[1]), minimo, limite };
}

function colherCupons(mem, posts, agora, pessoal = () => false) {
  const t = agora.getTime();
  const banco = (mem.cuponsBanco || []).filter(c => t - c.visto < validadeBanco(c.loja));
  for (const p of posts) {
    if (p.tipo !== 'cupom' || (p.cupons || []).length !== 1) continue;
    const codigo = p.cupons[0];
    if (pessoal(codigo) || CUPOM_RESTRITO.test(p.texto || '')) continue;
    const loja = lojaDoCupom(p);
    const cond = condicaoCupom([...(p.linhasCupom || []), p.texto].join(' '));
    if (!loja || !cond || !(cond.valor > 0)) continue;

    const visto = Math.min(t, Date.parse(p.quando) || t);
    if (t - visto >= validadeBanco(loja)) continue;
    const ja = banco.find(c => c.codigo === codigo && c.loja === loja);
    if (ja) { ja.visto = Math.max(ja.visto, visto); continue; }
    banco.push({ codigo, loja, ...cond, visto, fonte: p.id || null });
  }
  mem.cuponsBanco = banco.slice(-40);
  return mem.cuponsBanco;
}

function melhorCupom(mem, loja, preco, agora) {
  if (!preco || !loja) return null;
  const t = agora.getTime();
  let melhor = null;
  for (const c of mem.cuponsBanco || []) {
    if (c.loja !== loja || t - c.visto >= validadeBanco(c.loja) || (c.minimo || 0) > preco) continue;
    const desconto = c.tipo === 'R$' ? c.valor : Math.min(preco * c.valor / 100, c.limite || Infinity);
    if (!(desconto >= 3) || desconto >= preco * 0.6) continue;
    if (!melhor || desconto > melhor.desconto) melhor = { c, desconto };
  }
  if (!melhor) return null;
  const { c, desconto } = melhor;
  const texto = (c.tipo === 'R$' ? `R$${reaisCurto(c.valor)} OFF` : `${c.valor}% OFF`)
    + (c.minimo ? ` acima de R$${reaisCurto(c.minimo)}` : '') + (c.tipo === '%' && c.limite ? `, limite R$${reaisCurto(c.limite)}` : '');
  return { codigo: c.codigo, desconto: Math.round(desconto * 100) / 100, precoCom: Math.round((preco - desconto) * 100) / 100, texto };
}

async function garimpar({ canais = {}, amazonHtml = '', shopee = [], agora, cfg, mem, rede }) {
  const t = agora.getTime(), tentou = [];
  const lista = cfg.proibido || PROIBIDO_PADRAO;
  const resumo = mem.resumo || (mem.resumo = { lojas: {}, descartes: {} });
  const pula = (id, motivo) => { tentou.push([id, motivo]); resumo.descartes[motivo] = (resumo.descartes[motivo] || 0) + 1; };

  const querEletronico = cfg.eletronicoACada > 0 && (mem.semEletronico || 0) >= cfg.eletronicoACada - 1;
  const vez = (nome) => (querEletronico && ehEletronico(nome) ? 1 : 0);

  const pessoal = (c) => (cfg.canais || Object.keys(canais)).some(n => c.toUpperCase().includes(String(n).toUpperCase().slice(0, 5)));

  const recentes = [];
  for (const [canal, html] of Object.entries(canais))
    for (const p of lerCanalTelegram(html)) {
      const idade = p.quando ? t - Date.parse(p.quando) : Infinity;
      if (idade <= BANCO_HORAS * 36e5) recentes.push({ ...p, canal, ...lerPost(p.texto) });
    }
  colherCupons(mem, recentes, agora, pessoal);
  const daShopee = escolherShopee(shopee, mem, cfg, lista, querEletronico);
  if (daShopee && (mem.postados || 0) % 3 === 2 && (!querEletronico || ehEletronico(daShopee.nome))) return postShopee(daShopee, rede, melhorCupom(mem, 'shopee', daShopee.preco, agora));
  const posts = recentes.filter(p => (p.quando ? t - Date.parse(p.quando) : Infinity) <= cfg.idadeMaxMin * 6e4 && !mem.vistos[p.id]);

  const temCupom = (p) => ((p.cupons || []).length || p.dicaCupom ? 1 : 0);

  const alto = (p) => (ehAltoValor(p.nome || p.texto) ? 1 : 0);
  posts.sort((a, b) => (vez(b.nome || b.texto) - vez(a.nome || a.texto)) || (alto(b) - alto(a)) || (temCupom(b) - temCupom(a)) || (Date.parse(b.quando) - Date.parse(a.quando)));

  const converterTodos = async (links, nomePost) => {
    const out = [];
    for (const l of links) { const c = await converterLink(l, cfg, rede, true, nomePost); if (!c.ok) return { ok: false, motivo: c.motivo }; out.push(c); }
    return { ok: true, out };
  };

  let tentativas = 0;
  for (const tipo of ['produto', 'cupom']) {
    if (tipo === 'cupom' && (mem.cupons || 0) >= cfg.cuponsPorDia) continue;
    for (const p of posts.filter(x => x.tipo === tipo)) {
      if (tentativas >= cfg.maxTentativas) break;
      mem.vistos[p.id] = t;
      if (proibido(p.texto, lista)) { pula(p.id, 'proibido'); continue; }
      if (p.cupons.some(pessoal)) { pula(p.id, 'cupom_do_canal'); continue; }
      tentativas++;
      const principal = p.link || p.links[p.links.length - 1];
      if (!principal && tipo === 'produto') { pula(p.id, 'sem_link'); continue; }
      const c = principal ? await converterTodos([principal], p.nome) : { ok: false, motivo: 'sem_link' };
      if (!c.ok) {

        const loja = NOME_LOJA[plataformaDe(principal || '')] || '';
        if (tipo === 'cupom' && p.cupons.length && loja && !/selecionad|lista completa|mostrar mais/i.test(p.texto)) {
          return { acao: 'postar', tipo, chave: `cupom:${p.cupons.join(',')}`, fonte: p.id, imagem: '',
            texto: legendaCupom({ loja, linhasCupom: p.linhasCupom, cupons: p.cupons }) };
        }
        pula(p.id, c.motivo); continue;
      }
      let [prim] = c.out;
      if (tipo === 'produto') {

        if (prim.loja === 'shopee' && !/^shopee:\d+\.\d+$/.test(prim.chave)) {
          let achado = null;
          if (rede.shopeeBusca && !nomeFraco(p.nome)) {
            let lista = [];
            try { lista = (await rede.shopeeBusca(p.nome)) || []; } catch (e) { lista = []; }
            achado = lista.find(o => mesmoProduto(p.nome, o.nome) && quantidade(o.nome) === quantidade(p.nome)) || null;
          }
          if (!achado) { pula(p.id, 'shopee_sem_produto'); continue; }
          prim = { ...prim, url: achado.link, chave: achado.chave };
        }

        if (prim.loja === 'amazon' && !/^amazon:[A-Z0-9]{10}$/.test(prim.chave)) { pula(p.id, 'amazon_sem_produto'); continue; }
        if (mem.produtos[prim.chave]) { pula(p.id, 'repetido'); continue; }

        let nome = p.nome, d = {};

        if (prim.vitrine && prim.vitrine.preco) d = { nome: prim.vitrine.nome, foto: prim.vitrine.foto, preco: prim.vitrine.preco, precoDe: prim.vitrine.precoDe, aberta: true };
        if (prim.loja === 'amazon' && rede.pagina) {
          let html = '';
          try { html = await rede.pagina(`https://www.amazon.com.br/dp/${prim.chave.slice(7)}`); } catch (e) { html = ''; }
          d = lerPaginaAmazon(html);
        }

        const cat = prim.loja === 'mercadolivre' && rede.mlCatalogo && String(prim.url).match(/\/p\/(MLB\d+)/i);
        if (cat) { try { d = (await rede.mlCatalogo(cat[1].toUpperCase())) || {}; } catch (e) { d = {}; } }
        if (d.aberta && !d.preco) { pula(p.id, 'sem_preco_na_loja'); continue; }

        let sh = null;
        if (prim.loja === 'shopee' && rede.shopeeProduto && /^shopee:\d+\.\d+$/.test(prim.chave)) {
          const [lj, it] = prim.chave.slice(7).split('.');
          try { sh = await rede.shopeeProduto(lj, it); } catch (e) { sh = null; }
          if (sh && !lojaConfiavel(sh, cfg)) { pula(p.id, 'loja_pouco_confiavel'); continue; }
        }

        const idadePost = p.quando ? t - Date.parse(p.quando) : Infinity;
        if (prim.loja === 'mercadolivre' && !d.preco && idadePost > (cfg.idadeSemConferirMin || 30) * 6e4) { pula(p.id, 'ml_sem_conferir_antigo'); continue; }
        const daLoja = d.preco ? { preco: d.preco, precoDe: d.precoDe, cupom: d.cupom } : (sh ? { preco: sh.preco, menorOpcao: true } : null);
        const pr = conferirPreco(p, daLoja);
        if (!pr.ok) { pula(p.id, pr.motivo); continue; }

        if (d.nome && !nomeFraco(nome)) {
          const qp = quantidade(nome), ql = quantidade(d.nome);
          if (!mesmoProduto(nome, d.nome) || (qp > 1 && ql !== qp)) { pula(p.id, 'produto_diferente_do_post'); continue; }
        }
        if (d.nome && nomeFraco(nome)) nome = d.nome;
        if ((mem.recentes || []).includes(primeiraPalavra(nome))) { pula(p.id, 'parecido_com_recente'); continue; }
        if (cat && d.foto) d.foto = await fotoDaGaleria(d, rede);
        let imagem = d.foto || (sh && sh.foto) || await fotoDoPost(rede, p.foto);
        const descartada = !d.foto && !(sh && sh.foto) && !!p.foto && !imagem;
        if (nomeFraco(nome)) { pula(p.id, 'sem_nome'); continue; }
        if (!imagem) { pula(p.id, descartada ? 'foto_de_outro_grupo' : 'sem_foto'); continue; }
        const chamada = await pedirChamada(rede, nome);
        const campos = { ...p, ...(daLoja || deCrivel(p.preco, p.precoAntes) ? {} : { precoAntes: null }), ...pr.campos };
        const proprio = (campos.cupons || []).length > 0 || !!campos.dicaCupom;
        const cupomBanco = proprio ? null : melhorCupom(mem, prim.loja, campos.preco, agora);
        return { acao: 'postar', tipo, chave: prim.chave, fonte: p.id, imagem, link: prim.url, titulo: nome, foto_descartada: descartada, chamada_ia: !!chamada,
          preco_post: p.preco || null, preco_loja: daLoja ? daLoja.preco : null, comCupom: proprio || !!cupomBanco,
          texto: legendaAchado({ ...campos, nome, link: prim.url, chave: prim.chave, chamada, cupomBanco }) };
      }
      const chave = `cupom:${p.cupons.join(',') || prim.chave}`;
      if (mem.produtos[chave]) { pula(p.id, 'repetido'); continue; }
      return { acao: 'postar', tipo, chave, fonte: p.id, imagem: '',
        texto: legendaCupom({ loja: NOME_LOJA[prim.loja] || '', linhasCupom: p.linhasCupom, cupons: p.cupons, link: prim.url }) };
    }
    if (tipo === 'produto' && daShopee) return postShopee(daShopee, rede, melhorCupom(mem, 'shopee', daShopee.preco, agora));
    if (tipo === 'produto' && cfg.amazonTag) {
      const achados = lerAmazonDeals(amazonHtml)
        .filter(a => a.desconto >= cfg.descontoMin && !mem.produtos[`amazon:${a.asin}`] && !proibido(a.nome, lista))
        .sort((a, b) => (vez(b.nome) - vez(a.nome)) || (b.desconto - a.desconto));
      if (achados.length) {
        const a = achados[0];
        const chamada = await pedirChamada(rede, a.nome);
        const link = `https://www.amazon.com.br/dp/${a.asin}?tag=${encodeURIComponent(cfg.amazonTag)}`;
        const cupomBanco = melhorCupom(mem, 'amazon', a.preco, agora);
        return { acao: 'postar', tipo: 'produto', chave: `amazon:${a.asin}`, fonte: 'amazon/deals', imagem: a.foto || '', link, titulo: a.nome, chamada_ia: !!chamada,
          comCupom: !!cupomBanco,
          texto: legendaAchado({ nome: a.nome, preco: a.preco, precoAntes: a.precoAntes, prime: a.prime, chave: `amazon:${a.asin}`, chamada, cupomBanco,
            link: `https://www.amazon.com.br/dp/${a.asin}?tag=${encodeURIComponent(cfg.amazonTag)}` }) };
      }
    }
  }
  return { acao: 'nada', motivo: 'sem_oferta_convertivel', tentou };
}

const MODELO_CENA = 'google/gemini-3.1-flash-lite-image';

function precoEOffDaLegenda(texto) {
  const t = String(texto || '');
  const por = t.match(/\b[Pp]or R\$ ?([\d.]+(?:,\d{1,2})?)/);
  const off = t.match(/(\d{1,2})% OFF/);
  return { preco: por ? numero(por[1]) : null, off: off ? Number(off[1]) : 0 };
}

function cenaEmTudo(agora, cfg) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(cfg.cenaTodosAte || '')) && diaSP(agora) <= cfg.cenaTodosAte;
}

function ehDestaque(r, todos = false) {
  if (!r || r.acao !== 'postar' || r.tipo !== 'produto') return false;
  if (/^amazon:/.test(r.chave || '') || !/^https:\/\//.test(r.imagem || '')) return false;
  if (todos) return true;
  const { preco, off } = precoEOffDaLegenda(r.texto);
  return ehAltoValor(r.titulo) || off >= 40 || (preco || 0) >= 300;
}

function podeCena(mem, agora, cfg) {
  if (cenaEmTudo(agora, cfg)) cfg = { ...cfg, cenaPorDia: 150, cenaIntervalo: 0 };
  const n = cfg.cenaPorDia || 0;
  if (!n) return false;
  const dia = diaSP(agora);
  if (!mem.cena || mem.cena.dia !== dia) mem.cena = { dia, feitas: 0, tentativas: 0, ultimo: 0 };
  if (mem.cena.feitas >= n || mem.cena.tentativas >= n * 2) return false;
  return agora.getTime() - (mem.cena.ultimo || 0) >= (cfg.cenaIntervalo || 0) * 6e4;
}

function pedidoCena(foto, titulo) {
  const texto = `Product: ${String(titulo || '').slice(0, 120)}. Use the product in the attached photo EXACTLY as it is: same shape, colors, logos, labels, `
    + 'screen content style and number of items. Do not add, remove or change any part of the product, do not invent accessories or decorations, '
    + 'and do not add any text, price or watermark. Create a realistic square photo, like taken with a good smartphone by a real person in Brazil '
    + '(natural light, slight depth of field), showing this exact product in the most natural setting for it: in use at home, on display in a store, '
    + 'or held in a hand. Never show a phone, computer or TV screen (unless the product itself is that device) and never show any brand name, logo or product name that is not printed on the product itself. '
    + 'Scene objects are fine in the background, but nothing may touch, cover or sit on top of the product. '
    + 'The product must be the clear hero of the photo, large and in focus.';
  return { model: MODELO_CENA, modalities: ['image', 'text'],
    messages: [{ role: 'user', content: [{ type: 'text', text: texto }, { type: 'image_url', image_url: { url: foto } }] }] };
}

function imagemDaResposta(r) {
  const m = r && r.choices && r.choices[0] && r.choices[0].message;
  const url = m && m.images && m.images[0] && m.images[0].image_url && m.images[0].image_url.url;
  return typeof url === 'string' && /^data:image\/(png|jpe?g|webp);base64,/.test(url) ? url : null;
}

function pedidoConferencia(foto, nova, modelo) {
  const texto = 'Imagem 1: foto original do produto, da loja. Imagem 2: foto nova em cena. O produto da imagem 2 é exatamente o mesmo da imagem 1? '
    + 'Confira marca e letras escritas no produto (idênticas, letra por letra), cores, formato e quantidade de itens. '
    + 'Ignore objetos do cenário (móveis, plantas, roupas, objetos de fundo) que claramente não fazem parte do que é vendido. '
    + 'Diga false se o produto mudou, se apareceu algo que parece vir junto com o produto, ou se a imagem 2 for igual à imagem 1 sem cena nenhuma. '
    + 'Responda só JSON: {"igual": true ou false, "motivo": "curto"}';
  return { model: modelo || MODELO_CHAMADA, temperature: 0,
    messages: [{ role: 'user', content: [{ type: 'text', text: texto }, { type: 'image_url', image_url: { url: foto } }, { type: 'image_url', image_url: { url: nova } }] }] };
}

function pedidoTextos(url, modelo) {
  const texto = 'Transcreva, letra por letra, exatamente como aparece, todo texto escrito no PRODUTO desta foto (marca, modelo, rótulos; '
    + 'ignore textos do cenário e o que aparece na tela). Não corrija grafia. Responda só JSON: {"textos": ["..."]}';
  return { model: modelo || MODELO_CHAMADA, temperature: 0,
    messages: [{ role: 'user', content: [{ type: 'text', text: texto }, { type: 'image_url', image_url: { url } }] }] };
}

function textosDaResposta(texto) {
  const t = String(texto || '');
  try {
    const j = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
    if (!Array.isArray(j.textos)) return null;
    const palavras = j.textos.join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().split(/[^A-Z0-9]+/);
    return palavras.filter(w => w.length >= 3 && /[A-Z]/.test(w));
  } catch (e) { return null; }
}

function distancia(a, b) {
  if (Math.abs(a.length - b.length) > 2) return 3;
  let ant = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const at = [i];
    for (let j = 1; j <= b.length; j++) at[j] = Math.min(ant[j] + 1, at[j - 1] + 1, ant[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    ant = at;
  }
  return ant[b.length];
}

function problemaNoTexto(daLoja, daNova) {
  if (!daLoja || !daNova) return 'leitura falhou';
  const loja = new Set(daLoja), nova = new Set(daNova);
  for (const w of nova) {
    if (loja.has(w) || w.length < 4) continue;
    const parecida = [...loja].find(o => o.length >= 4 && distancia(o, w) <= 2);
    if (parecida) return `${parecida} virou ${w}`;
  }
  const conta = {};
  for (const w of daLoja) conta[w] = (conta[w] || 0) + 1;
  const marca = Object.keys(conta).filter(w => conta[w] >= 2 && !nova.has(w));
  return marca.length ? `sumiu ${marca.slice(0, 2).join(', ')}` : null;
}

function pedidoMarcaNova(foto, nova, modelo) {
  const texto = 'Imagem 1: foto original do produto, da loja. Imagem 2: foto nova em cena, feita por IA. '
    + 'Leia todo texto visível nas duas (produto, caixa, embalagem, telas, etiquetas, cenário). '
    + 'A imagem 2 mostra algum NOME DE MARCA ou NOME DE PRODUTO (ex.: AirPods, iPhone, Samsung, Nike) que NÃO aparece na imagem 1? '
    + 'Palavras comuns do cenário (livro, caneca, placa de rua) não contam, só marca ou nome de produto. '
    + 'Responda só JSON: {"marcaNova": true ou false, "qual": "curto"}';
  return { model: modelo || MODELO_CHAMADA, temperature: 0,
    messages: [{ role: 'user', content: [{ type: 'text', text: texto }, { type: 'image_url', image_url: { url: foto } }, { type: 'image_url', image_url: { url: nova } }] }] };
}

function marcaNovaDaResposta(texto) {
  const t = String(texto || '');
  try { const j = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); return { nova: j.marcaNova !== false, qual: String(j.qual || '').slice(0, 60) }; }
  catch (e) { return { nova: true, qual: 'resposta ilegível' }; }
}

function conferenciaDaResposta(texto) {
  const t = String(texto || '');
  try { const j = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); return { igual: j.igual === true, motivo: String(j.motivo || '').slice(0, 120) }; }
  catch (e) { return { igual: false, motivo: 'resposta ilegível' }; }
}

async function comFotoEmCena(r, mem, agora, cfg, rede) {
  if (!rede || !rede.fotoEmCena || !rede.confereCena || !ehDestaque(r, cfg.cenaSempre || cenaEmTudo(agora, cfg)) || !podeCena(mem, agora, cfg)) return r;
  const log = [];
  for (let i = 0; i < 2 && podeCena(mem, agora, cfg); i++) {
    mem.cena.tentativas++;
    try {
      const nova = await rede.fotoEmCena(r.imagem, r.titulo);
      if (!nova) { log.push('sem imagem'); continue; }
      const c = await rede.confereCena(r.imagem, nova);
      if (c.igual) { mem.cena.feitas++; mem.cena.ultimo = agora.getTime(); return { ...r, cena: nova, cena_log: log.concat('ok') }; }
      log.push('recusada: ' + c.motivo);
    } catch (e) { log.push('erro'); }
  }
  return { ...r, cena_log: log };
}

async function hospedarCena(r, rede) {
  if (!r || !/^data:image\//.test(r.cena || '') || !rede || !rede.guardarImagem) return r;
  try { const url = await rede.guardarImagem(r.cena); return /^https:\/\//.test(url || '') ? { ...r, cena: url } : r; }
  catch (e) { return r; }
}

function ofertasDoReel(mem, dia) {
  const c = mem.cenasDoDia && mem.cenasDoDia.dia === dia ? mem.cenasDoDia.lista || [] : [];
  const vistos = new Set();
  return c.map(x => ({ x, d: dadosDoStatus({ ...x, cena: true }) }))
    .filter(({ d }) => d && d.f && !vistos.has(d.n) && vistos.add(d.n))
    .sort((a, b) => (1 - a.d.por / a.d.de) < (1 - b.d.por / b.d.de) ? 1 : -1)

    .slice(0, 3).map(({ d }) => ({ n: nomeCurto(d.n), de: d.de, por: d.por, f: d.f, l: d.l }));
}

function linkDoReel(base, segredo, ofertas, v) {
  if (!base || !segredo || !crypto || !Array.isArray(ofertas) || ofertas.length < 2) return null;
  const d = base64url(JSON.stringify({ o: ofertas, v }));
  const a = crypto.createHmac('sha256', String(segredo)).update('reel:' + d).digest('hex').slice(0, 24);
  return `${String(base).replace(/\/+$/, '')}/reel?d=${d}&a=${a}`;
}

function legendaDoReel(ofertas) {
  return [`\u{1F525} ${ofertas.length} achados que passaram hoje no grupo:`, '',
    ...ofertas.map((o, i) => `${i + 1}. ${o.n}: de R$ ${reaisCurto(o.de)} por R$ ${reaisCurto(o.por)}`), '',
    'Preços vistos hoje nas lojas. Podem mudar a qualquer momento.', '',
    '\u{1F449} O link do grupo grátis de ofertas no WhatsApp está na bio.', '',
    '#publi #ofertas #promocao #achadinhos #descontos'].join('\n');
}

async function passoDoReel(mem, agora, cfg, http, env) {
  if (!cfg.reelOfertas || !env.META_IG_USER_ID || !env.META_ACCESS_TOKEN) return null;
  const dia = diaSP(agora);
  if (horaSP(agora) < (cfg.reelHora || 19)) return null;
  let st = mem.reelOfertas && mem.reelOfertas.dia === dia ? mem.reelOfertas : { dia, tent: 0 };
  mem.reelOfertas = st;
  if (st.feito || st.tent >= 3) return null;
  const G = 'https://graph.facebook.com/v21.0/', tok = encodeURIComponent(env.META_ACCESS_TOKEN);
  try {
    if (!st.container) {
      const ofertas = ofertasDoReel(mem, dia);
      if (ofertas.length < 2) return { passo: 'poucas_ofertas', n: ofertas.length };
      const v = new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' }).format(agora);
      const url = linkDoReel(env.ENCURTADOR_URL, env.ENCURTADOR_SEGREDO, ofertas, v);
      if (!url) return { passo: 'sem_encurtador' };
      st.tent++;

      const t = await http.httpRequest({ method: 'GET', url, returnFullResponse: true, ignoreHttpStatusErrors: true, encoding: 'arraybuffer', timeout: 170000 });
      if (t.statusCode !== 200) return { passo: 'video_falhou', status: t.statusCode };
      const c = await http.httpRequest({ method: 'POST', url: `${G}${encodeURIComponent(env.META_IG_USER_ID)}/media`, json: true, timeout: 60000,
        body: { media_type: 'REELS', video_url: url, caption: legendaDoReel(ofertas), share_to_feed: true, access_token: env.META_ACCESS_TOKEN } });
      if (!c || !c.id) return { passo: 'conteiner_falhou' };
      st.container = c.id;
      return { passo: 'criou', ofertas: ofertas.length };
    }
    const sc = await http.httpRequest({ method: 'GET', json: true, timeout: 15000, url: `${G}${st.container}?fields=status_code&access_token=${tok}` });
    const status = sc && sc.status_code;
    if (status === 'ERROR' || status === 'EXPIRED') { st.container = null; return { passo: 'meta_recusou' }; }
    if (status !== 'FINISHED') return { passo: 'processando' };
    const r = await http.httpRequest({ method: 'POST', url: `${G}${encodeURIComponent(env.META_IG_USER_ID)}/media_publish`, json: true, timeout: 60000,
      body: { creation_id: st.container, access_token: env.META_ACCESS_TOKEN } });
    if (r && r.id) { st.feito = r.id; return { passo: 'publicou', id: r.id }; }
    return { passo: 'publicar_falhou' };
  } catch (e) { return { passo: 'erro' }; }
}

const DIAS_ACHADOS = [0, 1, 3, 5];   // dom, seg, qua, sex
const diaDaSemanaSP = (agora) => ({ Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 })[new Intl.DateTimeFormat('en-US', { timeZone: 'America/Sao_Paulo', weekday: 'short' }).format(agora)];

function nomeCurto(nome) {
  let n = String(nome || '').replace(/\s+/g, ' ').trim();
  const corte = n.search(/,| - | \| | para | com /i);
  if (corte > 12) n = n.slice(0, corte);
  if (n.length <= 44) return n;
  const p = n.slice(0, 45).split(' '); p.pop();
  return p.join(' ');
}

function ofertasDosAchados(mem, agora) {
  const limite = agora.getTime() - 7 * 864e5, usados = new Set(mem.achadosUsados || []);
  const vistos = new Set();
  const lista = (mem.cenasSemana || []).filter(x => x && x.quando > limite && !usados.has(x.chave))
    .map(x => ({ x, d: dadosDoStatus({ ...x, cena: true }) }))
    .filter(({ d }) => d && d.f && !vistos.has(d.n) && vistos.add(d.n))
    .map(({ x, d }) => ({ chave: x.chave, n: nomeCurto(d.n), de: d.de, por: d.por, f: d.f, l: d.l,
      v: new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' }).format(new Date(x.quando)), off: 1 - d.por / d.de }));
  const melhores = (l) => [...l].sort((a, b) => b.off - a.off).slice(0, 5).sort((a, b) => a.por - b.por);
  const ate = (v) => lista.filter(o => o.por <= v);
  let t = '', esc;
  if (ate(50).length >= 4) { t = 'abaixo de R$ 50'; esc = melhores(ate(50)); }
  else if (ate(100).length >= 4) { t = 'abaixo de R$ 100'; esc = melhores(ate(100)); }
  else esc = melhores(lista);
  return { t, o: esc.length >= 3 ? esc.map(({ off, ...o }) => o) : [] };
}

function linksDosAchados(base, segredo, achados) {
  if (!base || !segredo || !crypto || !achados || achados.o.length < 3) return null;
  const d = base64url(JSON.stringify({ t: achados.t, o: achados.o.map(({ chave, ...o }) => o) }));
  const a = crypto.createHmac('sha256', String(segredo)).update('achados:' + d).digest('hex').slice(0, 24);
  const raiz = `${String(base).replace(/\/+$/, '')}/achados?d=${d}&a=${a}&i=`;
  return Array.from({ length: achados.o.length + 2 }, (_, i) => raiz + i);
}

function legendaDosAchados(achados) {
  const titulo = achados.t ? `${achados.o.length} achados ${achados.t}` : `${achados.o.length} achados da semana`;
  return [`\u{1F525} ${titulo} que passaram no nosso grupo:`, '',
    ...achados.o.map((o, i) => `${i + 1}. ${o.n}: R$ ${reaisCurto(o.por)} (de R$ ${reaisCurto(o.de)}), em ${o.v}`), '',
    'Preços vistos nas lojas nos dias indicados. Podem ter mudado.', '',
    'Qual você levaria? Comenta o número \u{1F447}', '',
    '\u{1F449} O link do grupo grátis de ofertas no WhatsApp está na bio.', '',
    '#publi #achados #achadinhos #ofertas #promocao'].join('\n');
}

async function passoDosAchados(mem, agora, cfg, http, env) {
  if (!cfg.achados || !env.META_IG_USER_ID || !env.META_ACCESS_TOKEN) return null;
  if (!DIAS_ACHADOS.includes(diaDaSemanaSP(agora)) || horaSP(agora) < (cfg.achadosHora || 18)) return null;
  const dia = diaSP(agora);
  const st = mem.achadosIG && mem.achadosIG.dia === dia ? mem.achadosIG : { dia, tent: 0 };
  mem.achadosIG = st;
  if (st.feito || st.tent >= 3) return null;
  const G = 'https://graph.facebook.com/v21.0/', ig = encodeURIComponent(env.META_IG_USER_ID), tok = env.META_ACCESS_TOKEN;
  const status = async (id) => { const r = await http.httpRequest({ method: 'GET', json: true, timeout: 15000, url: `${G}${id}?fields=status_code&access_token=${encodeURIComponent(tok)}` }); return r && r.status_code; };
  try {
    if (!st.filhos) {
      const ach = ofertasDosAchados(mem, agora);
      if (ach.o.length < 3) return { passo: 'poucas_ofertas', n: ach.o.length };
      const urls = linksDosAchados(env.ENCURTADOR_URL, env.ENCURTADOR_SEGREDO, ach);
      if (!urls) return { passo: 'sem_encurtador' };
      st.tent++;

      for (const u of urls) {
        const t = await http.httpRequest({ method: 'GET', url: u, returnFullResponse: true, ignoreHttpStatusErrors: true, encoding: 'arraybuffer', timeout: 60000 });
        if (t.statusCode !== 200) return { passo: 'tela_falhou', status: t.statusCode };
      }
      const filhos = [];
      for (const u of urls) {
        const c = await http.httpRequest({ method: 'POST', url: `${G}${ig}/media`, json: true, timeout: 60000, body: { image_url: u, is_carousel_item: true, access_token: tok } });
        if (!c || !c.id) return { passo: 'item_falhou' };
        filhos.push(c.id);
      }
      st.filhos = filhos; st.legenda = legendaDosAchados(ach); st.chaves = ach.o.map(o => o.chave);
      return { passo: 'itens', n: filhos.length };
    }
    if (!st.container) {
      const sts = [];
      for (const f of st.filhos) sts.push(await status(f));
      if (sts.some(x => x === 'ERROR' || x === 'EXPIRED')) { st.filhos = null; return { passo: 'meta_recusou_item' }; }
      if (sts.some(x => x && x !== 'FINISHED')) return { passo: 'processando_itens' };
      const c = await http.httpRequest({ method: 'POST', url: `${G}${ig}/media`, json: true, timeout: 60000,
        body: { media_type: 'CAROUSEL', children: st.filhos.join(','), caption: st.legenda, access_token: tok } });
      if (!c || !c.id) return { passo: 'carrossel_falhou' };
      st.container = c.id;
      return { passo: 'carrossel' };
    }
    const sc = await status(st.container);
    if (sc === 'ERROR' || sc === 'EXPIRED') { st.container = null; st.filhos = null; return { passo: 'meta_recusou' }; }
    if (sc && sc !== 'FINISHED') return { passo: 'processando' };
    const r = await http.httpRequest({ method: 'POST', url: `${G}${ig}/media_publish`, json: true, timeout: 60000, body: { creation_id: st.container, access_token: tok } });
    if (r && r.id) {
      st.feito = r.id;
      mem.achadosUsados = [...(mem.achadosUsados || []), ...(st.chaves || [])].slice(-60);
      return { passo: 'publicou', id: r.id };
    }
    return { passo: 'publicar_falhou' };
  } catch (e) { return { passo: 'erro' }; }
}

function chamadaDoRascunho(texto, nome) {
  const l = String(texto || '').split('\n').map(x => x.trim()).find(Boolean) || '';
  const t = l.replace(/[\p{Extended_Pictographic}\uFE0F*_~]/gu, '').trim();
  if (!/\p{Lu}/u.test(t) || t !== t.toUpperCase() || /https?:|R\$/i.test(t)) return null;
  if (nome && t.toUpperCase() === String(nome).trim().toUpperCase()) return null;
  return limparChamada(t, nome);
}

async function pedirChamada(rede, nome) {
  if (!rede || !rede.chamada) return null;
  try { return await rede.chamada(nome); } catch (e) { return null; }
}

function registrarPostado(mem, { chave, tipo, eletronico }, agora) {
  mem.postados = (mem.postados || 0) + 1;
  if (tipo !== 'cupom') mem.semEletronico = eletronico ? 0 : (mem.semEletronico || 0) + 1;
  mem.ultimo = agora.getTime();
  if (tipo === 'cupom') mem.cupons = (mem.cupons || 0) + 1;
  if (chave) mem.produtos[chave] = agora.getTime();
  return mem;
}

