  : '\u274C Não consegui mostrar a prévia: ' + (r.erro || 'a Z-API não respondeu') } }];
return [{ json: { resposta: r.ok
  ? '\u2705 Postado no grupo de ofertas.' + (aviso ? '\n' + aviso : '')
  : '\u274C Não consegui postar no grupo: ' + (r.erro || 'a Z-API não respondeu') } }];
